const TABS = [
  ["overview", "Overview", "overview.view", "home", "Workspace"],
  ["analytics", "Analytics", "analytics.view", "analytics", "Workspace"],
  ["users", "Students", "users.view", "user", "Learning"],
  ["subscriptions", "Subscriptions", "subscriptions.view", "layers", "Learning"],
  ["content", "Content", "content.view", "file", "Library"],
  ["questions", "Questions", "assessments.view", "file-question", "Library"],
  ["notifications", "Notifications", "notifications.view", "bell", "Engagement"],
  ["reports", "Moderation", "moderation.view", "messages", "Engagement"],
  ["audit", "Activity", "audit.view", "activity", "Governance"],
  ["purchases", "Payments", "payments.view", "coins", "Governance"],
  ["exports", "Exports", "reports.export", "file", "Governance"],
  ["system", "System", "system_health.view", "activity", "Platform"],
  ["settings", "Settings", "configuration.view", "settings", "Platform"]
];

const NAV_GROUPS = ["Workspace", "Learning", "Library", "Engagement", "Governance", "Platform"];

function humanize(value) {
  return String(value || "Not available").replaceAll("_", " ").replace(/\b\w/g, (letter) => letter.toUpperCase());
}

function shortDate(value) {
  if (!value) return "—";
  return formatDateTime(value);
}

function money(value, currency = "USD", exponent = 2) {
  const amount = Number(value);
  if (!Number.isFinite(amount)) return "—";
  try { return formatNumber(amount / Math.pow(10, Number(exponent) || 2), { style: "currency", currency, minimumFractionDigits: 0, maximumFractionDigits: Number(exponent) || 2 }); }
  catch { return `${amount} ${currency}`; }
}

function dateWindow(days) {
  const end = new Date();
  const start = new Date(end);
  start.setUTCDate(start.getUTCDate() - days + 1);
  return { from: start.toISOString().slice(0, 10), to: end.toISOString().slice(0, 10) };
}

function Notice({ error = null, message = "" }) {
  const fields = error?.fields && typeof error.fields === "object"
    ? Object.entries(error.fields).flatMap(([name, values]) => `${humanize(name)}: ${Array.isArray(values) ? values.join(" ") : values}`)
    : [];
  if (!error && !message) return null;
  return <div className={`form-alert ${error ? "error" : "success"}`} role={error ? "alert" : "status"}>{error?.message || message}{fields.map((field) => <small key={field}>{field}</small>)}</div>;
}

function Pager({ page, count, onPage }) {
  const canBack = page > 1;
  const canNext = page * 25 < count;
  return <div className="operations-pager"><span>{count} server record{count === 1 ? "" : "s"}</span><div><button className="btn btn-soft compact" type="button" disabled={!canBack} onClick={() => onPage(page - 1)}>Previous</button><button className="btn btn-soft compact" type="button" disabled={!canNext} onClick={() => onPage(page + 1)}>Next</button></div></div>;
}

function AdminTabs({ operationsSession, active }) {
  const visibleTabs = TABS.filter(([, , capability]) => hasOperationalCapability(operationsSession, capability));
  const [collapsed, setCollapsed] = useState(false);
  return <aside className={`creator-studio-rail ${collapsed ? "is-collapsed" : ""}`}>
    <div className="creator-studio-brand"><span className="creator-studio-mark">L</span><span><strong>LOCK IN</strong><small>Creator Studio</small></span><button type="button" onClick={() => setCollapsed((value) => !value)} aria-label={collapsed ? "Expand navigation" : "Collapse navigation"}><Icon name={collapsed ? "chevron-right" : "chevron-left"} size={17} /></button></div>
    <nav aria-label="Creator Studio areas">{NAV_GROUPS.map((group) => {
      const items = visibleTabs.filter(([, , , , itemGroup]) => itemGroup === group);
      if (!items.length) return null;
      return <section key={group}><p>{group}</p>{items.map(([key, label, , icon]) => <Link key={key} to={`/operations/admin/${key}`} className={active === key ? "active" : ""} aria-current={active === key ? "page" : undefined}><Icon name={icon} size={18} /><span>{label}</span></Link>)}</section>;
    })}</nav>
    <div className="creator-studio-rail-note"><Icon name="lock" size={16} /><span>Server-authorized controls</span></div>
  </aside>;
}

function CreatorStudioHeader({ active, allowed }) {
  const navigate = useNavigate();
  const location = useLocation();
  const activeTab = allowed.find(([key]) => key === active);
  const [query, setQuery] = useState(() => new URLSearchParams(location.search).get("q") || "");
  function search(event) {
    event.preventDefault();
    const clean = query.trim();
    navigate(`/operations/admin/users${clean ? `?q=${encodeURIComponent(clean)}` : ""}`);
  }
  return <header className="creator-studio-topbar">
    <div><p>Creator Studio</p><h1>{activeTab?.[1] || "Overview"}</h1></div>
    {/* This shortcut jumps to the student list with the query applied. On that
        list it would be a second field driving the same search, so the screen
        keeps only its own. */}
    {active !== "users" && <form className="creator-global-search" role="search" onSubmit={search}><Icon name="search" size={18} /><input type="search" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Find a student by name or email" aria-label="Search Creator Studio" /><kbd>Enter</kbd></form>}
    <label className="field operations-mobile-selector"><span>Studio area</span><select value={active} onChange={(event) => navigate(`/operations/admin/${event.target.value}`)}>{allowed.map(([key, label]) => <option value={key} key={key}>{label}</option>)}</select></label>
    <div className="creator-operator"><span><Icon name="shield-alert" size={18} /></span><div><strong>Operator</strong><small>Protected session</small></div></div>
  </header>;
}

function FormButton({ pending, children, className = "btn btn-primary", ...props }) {
  return <button className={className} type="submit" disabled={pending} {...props}>{pending ? "Working…" : children}</button>;
}

function ActivityChart({ points, days }) {
  const filled = useMemo(() => {
    const values = new Map((points || []).map((point) => [point.day, Number(point.sessions) || 0]));
    const { from } = dateWindow(days);
    const cursor = new Date(`${from}T00:00:00Z`);
    return Array.from({ length: days }, (_, index) => {
      const day = new Date(cursor); day.setUTCDate(cursor.getUTCDate() + index);
      const key = day.toISOString().slice(0, 10);
      return { day: key, value: values.get(key) || 0 };
    });
  }, [days, points]);
  const width = 760; const height = 250; const pad = 28;
  const max = Math.max(1, ...filled.map((point) => point.value));
  const coords = filled.map((point, index) => ({ ...point, x: pad + (index / Math.max(1, filled.length - 1)) * (width - pad * 2), y: height - pad - (point.value / max) * (height - pad * 2) }));
  const line = coords.map((point, index) => `${index ? "L" : "M"}${point.x.toFixed(1)},${point.y.toFixed(1)}`).join(" ");
  const area = coords.length ? `${line} L${coords.at(-1).x},${height - pad} L${coords[0].x},${height - pad} Z` : "";
  return <div className="creator-chart"><svg viewBox={`0 0 ${width} ${height}`} role="img" aria-label={`Daily study sessions over ${days} days`} preserveAspectRatio="none"><defs><linearGradient id="creator-chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="var(--creator-purple)" stopOpacity=".34" /><stop offset="1" stopColor="var(--creator-purple)" stopOpacity="0" /></linearGradient></defs>{[0, 1, 2, 3].map((row) => <line key={row} x1={pad} x2={width - pad} y1={pad + row * ((height - pad * 2) / 3)} y2={pad + row * ((height - pad * 2) / 3)} />)}<path className="creator-chart-area" d={area} /><path className="creator-chart-line" d={line} /></svg><div className="creator-chart-axis"><span>{filled[0]?.day || "—"}</span><span>Peak {formatNumber(max)}</span><span>{filled.at(-1)?.day || "—"}</span></div></div>;
}

function MetricCard({ label, value, hint, icon, tone = "purple" }) {
  return <article className={`creator-metric tone-${tone}`}><span><Icon name={icon} size={18} /></span><div><small>{label}</small><strong>{value ?? "—"}</strong><p>{hint}</p></div></article>;
}

function RangePicker({ days, onChange }) {
  return <div className="creator-range" aria-label="Analytics period">{[7, 30, 90].map((value) => <button key={value} type="button" className={days === value ? "active" : ""} onClick={() => onChange(value)}>{value}d</button>)}</div>;
}

function Overview() {
  const [days, setDays] = useState(30);
  const period = useMemo(() => dateWindow(days), [days]);
  const data = useAsyncData(() => Promise.all([adminControlApi.overview(), adminControlApi.analytics(period), adminControlApi.audit({ page: 1, pageSize: 6 })]).then(([overview, analytics, audit]) => ({ overview, analytics, audit })), [period.from, period.to]);
  if (data.loading) return <LoadingPanel />;
  if (data.error) return <ErrorPanel message={data.error} onRetry={data.reload} />;
  const { analytics, overview, audit } = data.data;
  const needs = [
    ["Content awaiting review", analytics.creators.content_awaiting_review, "content", "questions"],
    ["Failed payments", overview.queues?.failed_payments ?? analytics.revenue.failed_payments, "billing", "purchases"],
    ["Failed notifications", overview.queues?.failed_notifications ?? analytics.operations.failed_notification_deliveries, "notifications", "notifications"],
    ["Expiring in 14 days", analytics.subscriptions.upcoming_expirations, "subscriptions", "subscriptions"]
  ];
  return <div className="creator-overview">
    <section className="creator-metrics" aria-label="Platform summary">
      <MetricCard label="Total students" value={formatNumber(analytics.users.total)} hint={`${formatNumber(analytics.users.new_week)} joined this week`} icon="user" />
      <MetricCard label="Active subscriptions" value={formatNumber(analytics.subscriptions.active)} hint={`${formatNumber(analytics.subscriptions.trial)} trials`} icon="layers" tone="gold" />
      <MetricCard label="Online now" value={formatNumber(analytics.users.online_now)} hint="Seen in the last 5 minutes" icon="activity" tone="green" />
      <MetricCard label="Seen today" value={formatNumber(analytics.users.seen_today)} hint="Recorded account sessions" icon="eye" />
      <MetricCard label="New this week" value={formatNumber(analytics.users.new_week)} hint="Verified database accounts" icon="plus" />
      <MetricCard label="Study sessions today" value={formatNumber(analytics.learning.focus_sessions_today)} hint="Focus sessions started today" icon="clock" tone="gold" />
    </section>
    <section className="creator-overview-grid">
      <article className="creator-panel creator-panel-wide"><div className="creator-panel-heading"><div><p>Study activity</p><h2>Daily Focus sessions</h2><span>{analytics.period.from} — {analytics.period.to} · UTC</span></div><RangePicker days={days} onChange={setDays} /></div><ActivityChart points={analytics.learning.focus_activity || []} days={days} /><div className="creator-chart-summary"><span><b>{formatNumber(analytics.learning.focus_sessions)}</b> sessions</span><span><b>{formatNumber(analytics.learning.active_learners)}</b> learners</span><span><b>{Math.round(analytics.learning.focus_seconds / 3600)}h</b> focused</span></div></article>
      <article className="creator-panel creator-attention"><div className="creator-panel-heading"><div><p>Operations</p><h2>Needs attention</h2></div><span className="creator-status-dot">Live</span></div>{needs.map(([label, value, kind, target]) => <Link key={label} to={`/operations/admin/${target}`}><span className={`creator-attention-icon is-${kind}`}><Icon name={kind === "billing" ? "coins" : kind === "content" ? "file-question" : kind === "subscriptions" ? "layers" : "bell"} size={17} /></span><span><strong>{label}</strong><small>{Number(value) ? "Review queue" : "Nothing waiting"}</small></span><b>{formatNumber(value)}</b></Link>)}</article>
    </section>
    <section className="creator-lower-grid">
      <article className="creator-panel"><div className="creator-panel-heading"><div><p>Subjects</p><h2>Most active</h2></div></div>{analytics.learning.most_active_subjects?.length ? analytics.learning.most_active_subjects.slice(0, 5).map((subject, index) => <div className="creator-ranked-row" key={subject.learning_object__published_version__academic_node_id}><span>{index + 1}</span><div><strong>{subject.learning_object__published_version__academic_node__title}</strong><small>{formatNumber(subject.learners)} learners</small></div><b>{formatNumber(subject.uses)}</b></div>) : <EmptyState title="No subject activity" text="Activity appears after students open published learning material." />}</article>
      <article className="creator-panel"><div className="creator-panel-heading"><div><p>Content</p><h2>Most opened sheets</h2></div><Link to="/operations/admin/content">View library</Link></div>{analytics.learning.most_used_materials.length ? analytics.learning.most_used_materials.slice(0, 5).map((material, index) => <div className="creator-ranked-row" key={material.learning_object_id}><span>{index + 1}</span><div><strong>{material.learning_object__published_version__title || "Untitled sheet"}</strong><small>Stored learning progress</small></div><b>{formatNumber(material.uses)}</b></div>) : <EmptyState title="No sheet activity" text="Published sheet usage will appear here." />}</article>
      <article className="creator-panel creator-recent"><div className="creator-panel-heading"><div><p>Governance</p><h2>Recent activity</h2></div><Link to="/operations/admin/audit">Open log</Link></div>{audit.results.length ? audit.results.slice(0, 5).map((record) => <div className="creator-activity-row" key={record.id}><span><Icon name="activity" size={16} /></span><div><strong>{humanize(record.action)}</strong><small>{record.actor_name || "System"} · {shortDate(record.occurred_at)}</small></div></div>) : <EmptyState title="No recent activity" text="Authorized actions will appear in the immutable audit log." />}</article>
    </section>
  </div>;
}

function Analytics() {
  const [days, setDays] = useState(30);
  const period = useMemo(() => dateWindow(days), [days]);
  const data = useAsyncData(() => adminControlApi.analytics(period), [period.from, period.to]);
  if (data.loading) return <LoadingPanel />;
  if (data.error) return <ErrorPanel message={data.error} onRetry={data.reload} />;
  const analytics = data.data;
  return <div className="creator-analytics">
    <div className="creator-page-tools"><div><p>Stored aggregates</p><h2>Learning and business signals</h2><span>{analytics.period.from} — {analytics.period.to} · UTC</span></div><RangePicker days={days} onChange={setDays} /></div>
    <section className="creator-metrics creator-metrics-four">
      <MetricCard label="Active learners" value={formatNumber(analytics.learning.active_learners)} hint={`${formatNumber(analytics.learning.focus_sessions)} Focus sessions`} icon="user" />
      <MetricCard label="Completion rate" value={`${analytics.learning.completion_rate}%`} hint={`${formatNumber(analytics.learning.material_completions)} completions`} icon="check" tone="green" />
      <MetricCard label="Net revenue" value={money(analytics.revenue.net_minor)} hint={`${formatNumber(analytics.revenue.paying_users)} paying students`} icon="coins" tone="gold" />
      <MetricCard label="Subscription churn" value={analytics.subscriptions.churn_rate == null ? "—" : `${analytics.subscriptions.churn_rate}%`} hint={`${formatNumber(analytics.subscriptions.renewals)} renewals`} icon="layers" />
    </section>
    <section className="creator-overview-grid">
      <article className="creator-panel creator-panel-wide"><div className="creator-panel-heading"><div><p>Engagement</p><h2>Daily Focus sessions</h2></div><span>{formatNumber(analytics.learning.active_learners)} unique learners</span></div><ActivityChart points={analytics.learning.focus_activity || []} days={days} /></article>
      <article className="creator-panel"><div className="creator-panel-heading"><div><p>Assessment quality</p><h2>Outcomes</h2></div></div><div className="creator-fact-list"><div><span>Quiz attempts</span><b>{formatNumber(analytics.learning.quiz_attempts)}</b></div><div><span>Exam attempts</span><b>{formatNumber(analytics.learning.exam_attempts)}</b></div><div><span>Average score</span><b>{analytics.learning.average_score == null ? "—" : `${Math.round(analytics.learning.average_score)}%`}</b></div><div><span>Pass rate</span><b>{analytics.learning.pass_rate == null ? "—" : `${analytics.learning.pass_rate}%`}</b></div></div></article>
    </section>
    <section className="creator-lower-grid creator-lower-grid-two">
      <article className="creator-panel"><div className="creator-panel-heading"><div><p>Subscriptions</p><h2>Lifecycle</h2></div></div><div className="creator-fact-list"><div><span>Active</span><b>{formatNumber(analytics.subscriptions.active)}</b></div><div><span>Trial</span><b>{formatNumber(analytics.subscriptions.trial)}</b></div><div><span>Expired</span><b>{formatNumber(analytics.subscriptions.expired)}</b></div><div><span>Cancelled</span><b>{formatNumber(analytics.subscriptions.cancelled)}</b></div></div></article>
      <article className="creator-panel"><div className="creator-panel-heading"><div><p>Revenue</p><h2>Payment health</h2></div></div><div className="creator-fact-list"><div><span>Gross</span><b>{money(analytics.revenue.gross_minor)}</b></div><div><span>Refunded</span><b>{money(analytics.revenue.refund_total_minor)}</b></div><div><span>Average order</span><b>{money(analytics.revenue.average_order_minor)}</b></div><div><span>Failed payments</span><b>{formatNumber(analytics.revenue.failed_payments)}</b></div></div></article>
    </section>
  </div>;
}

function Users({ operationsSession, initialQuery = "" }) {
  const [query, setQuery] = useState(initialQuery); const [status, setStatus] = useState(""); const [role, setRole] = useState(""); const [ordering, setOrdering] = useState("-date_joined"); const [page, setPage] = useState(1); const [selected, setSelected] = useState(null);
  useEffect(() => { setQuery(initialQuery); setPage(1); }, [initialQuery]);
  const list = useAsyncData(() => adminControlApi.users({ page, query, status, role, ordering }), [page, query, status, role, ordering]);
  return <section className="operations-workspace"><div className="creator-filter-bar"><SearchBar label="Search students" value={query} onChange={(value) => { setQuery(value); setPage(1); }} placeholder="Name or email" /><label className="field"><span>Status</span><select value={status} onChange={(event) => { setStatus(event.target.value); setPage(1); }}><option value="">All statuses</option><option value="active">Active</option><option value="suspended">Suspended</option><option value="deleted">Deactivated</option></select></label><label className="field"><span>Role</span><select value={role} onChange={(event) => { setRole(event.target.value); setPage(1); }}><option value="">All roles</option><option value="student">Student</option><option value="creator">Creator</option><option value="moderator">Moderator</option><option value="administrator">Administrator</option></select></label><label className="field"><span>Sort</span><select value={ordering} onChange={(event) => { setOrdering(event.target.value); setPage(1); }}><option value="-date_joined">Newest</option><option value="date_joined">Oldest</option><option value="full_name">Name</option><option value="email">Email</option></select></label></div>
    {list.loading ? <LoadingPanel variant="list" /> : list.error ? <ErrorPanel message={list.error} onRetry={list.reload} /> : <><section className="creator-panel creator-table-panel"><div className="creator-panel-heading"><div><p>Directory</p><h2>Students</h2></div><span>{formatNumber(list.data.count)} records</span></div>{list.data.results.length ? <div className="creator-table-wrap"><table className="creator-table"><thead><tr><th>Student</th><th>Status</th><th>Cohort</th><th>Roles</th><th>Joined</th><th><span className="sr-only">Actions</span></th></tr></thead><tbody>{list.data.results.map((user) => <tr key={user.id}><td className="is-identity"><strong>{user.full_name || "Unnamed account"}</strong><small>{user.email}</small></td><td data-label="Status"><span className={`creator-badge is-${user.status}`}>{humanize(user.status)}</span></td><td data-label="Cohort">{user.cohort?.title || "—"}</td><td data-label="Roles">{user.product_roles.join(", ") || "Student"}</td><td data-label="Joined">{shortDate(user.date_joined)}</td><td className="is-actions"><button className="btn btn-soft compact" type="button" onClick={() => setSelected(user.id)}>View <Icon name="chevron-right" size={15} /></button></td></tr>)}</tbody></table></div> : <EmptyState title="No students found" text="No account matched these server-side filters." />}</section><Pager page={page} count={list.data.count} onPage={setPage} /></>}
    {selected && <UserDetail userId={selected} operationsSession={operationsSession} onClose={() => setSelected(null)} />}
  </section>;
}

function UserDetail({ userId, operationsSession, onClose }) {
  const detail = useAsyncData(() => adminControlApi.user(userId), [userId]);
  const [section, setSection] = useState("profile"); const [reason, setReason] = useState(""); const [pending, setPending] = useState(null); const [error, setError] = useState(null); const [confirm, setConfirm] = useState(null);
  async function run(action, extra = {}) { setPending(action); setError(null); try { await adminControlApi.userAction(userId, { action, reason, ...extra }); detail.reload(); setConfirm(null); } catch (requestError) { setError(requestError); } finally { setPending(null); } }
  if (detail.loading) return <LoadingPanel />;
  if (detail.error) return <ErrorPanel message={detail.error} onRetry={detail.reload} />;
  const user = detail.data; const canManage = hasOperationalCapability(operationsSession, "users.manage"); const canManageRoles = hasOperationalCapability(operationsSession, "operational_roles.manage");
  const actionReady = canManage && !pending && reason.trim().length >= 8;
  return <><button className="creator-detail-backdrop" type="button" aria-label="Close student detail" onClick={onClose} /><aside className="operations-detail creator-detail-drawer" role="dialog" aria-modal="true" aria-labelledby="student-detail-title"><header><div><span className={`creator-badge is-${user.status}`}>{humanize(user.status)}</span><h2 id="student-detail-title">{user.full_name || user.email}</h2><p>{user.email}</p></div><button className="btn btn-soft compact" type="button" onClick={onClose}><Icon name="x" size={17} />Close</button></header><nav className="creator-detail-tabs" aria-label="Student details">{[["profile", "Profile"], ["subscriptions", "Subscription"], ["usage", "Usage"], ["access", "Access"]].map(([key, label]) => <button type="button" key={key} className={section === key ? "active" : ""} onClick={() => setSection(key)}>{label}</button>)}</nav><Notice error={error} />
    {section === "profile" && <div className="creator-detail-section"><div className="operations-detail-grid"><div><h3>Identity</h3><p>{user.email_verified ? "Verified email" : "Unverified email"}</p><p>{user.cohort?.title || "No cohort assigned"}</p><p>Joined {shortDate(user.date_joined)}</p></div><div><h3>Account</h3><p>{humanize(user.preferred_language)} language</p><p>{user.sessions.length} recorded sessions</p><p>{user.product_roles.join(", ") || "student"}</p></div></div>{user.sessions.length > 0 && <section className="operations-inline-panel"><h3>Sessions</h3>{user.sessions.slice(0, 6).map((session) => <div className="creator-session-row" key={session.id}><span><strong>{session.device_label}</strong><small>Seen {shortDate(session.last_seen_at)}</small></span>{canManage && <button className="btn btn-soft compact" type="button" disabled={!actionReady} onClick={() => setConfirm({ action: "logout_session", extra: { session_id: session.id } })}>Log out</button>}</div>)}</section>}{canManage && <section className="operations-inline-panel creator-account-actions"><h3>Account controls</h3><label className="field"><span>Administrative reason</span><input value={reason} minLength={8} maxLength={500} onChange={(event) => setReason(event.target.value)} placeholder="At least 8 characters; saved to audit history" /></label><div className="operations-actions"><button className="btn btn-outline compact" type="button" disabled={!actionReady} onClick={() => setConfirm({ action: user.status === "active" ? "suspend" : "reactivate" })}>{user.status === "active" ? "Suspend" : "Restore"}</button><button className="btn btn-soft compact" type="button" disabled={!actionReady} onClick={() => setConfirm({ action: user.email_verified ? "unverify_email" : "verify_email" })}>{user.email_verified ? "Unverify email" : "Verify email"}</button><button className="btn btn-soft compact" type="button" disabled={!actionReady} onClick={() => setConfirm({ action: "password_reset" })}>Send password reset</button><button className="btn btn-soft compact" type="button" disabled={!actionReady} onClick={() => setConfirm({ action: "logout_all" })}>Log out all</button><button className="btn btn-danger compact" type="button" disabled={!actionReady || user.status === "deleted"} onClick={() => setConfirm({ action: "soft_delete" })}>Deactivate</button></div></section>}</div>}
    {section === "subscriptions" && <div className="creator-detail-section">{user.subscriptions.length ? user.subscriptions.map((subscription) => <article className="creator-detail-record" key={subscription.id}><div><strong>{subscription.plan_title || subscription.plan_code}</strong><small>{humanize(subscription.status)}</small></div><span>{subscription.remaining_days ?? "—"} days left</span></article>) : <EmptyState title="No subscriptions" text="This student has no subscription records." />}{user.purchases?.length > 0 && <section className="operations-inline-panel"><h3>Recent purchases</h3>{user.purchases.slice(0, 5).map((purchase) => <p key={purchase.id}>{money(purchase.amount_minor, purchase.currency, purchase.currency_exponent)} · {humanize(purchase.status)} · {shortDate(purchase.created_at)}</p>)}</section>}</div>}
    {section === "usage" && <div className="creator-detail-section"><div className="operations-detail-grid"><div><h3>Focus sessions</h3><strong>{formatNumber(user.learning_activity.focus_sessions.length)}</strong><p>Recent records available</p></div><div><h3>Assessments</h3><strong>{formatNumber(user.assessments.attempts.length)}</strong><p>{formatNumber(user.assessments.results.length)} recent results</p></div></div>{user.learning_activity.progress?.length ? <section className="operations-inline-panel"><h3>Recent learning progress</h3>{user.learning_activity.progress.slice(0, 8).map((entry) => <div className="creator-session-row" key={entry.learning_object_id}><span><strong>{entry.learning_object__published_version__title || "Learning material"}</strong><small>{humanize(entry.status)} · {entry.completion_percent}%</small></span><small>{shortDate(entry.updated_at)}</small></div>)}</section> : <EmptyState title="No recent learning activity" text="Usage will appear after the student studies published material." />}</div>}
    {section === "access" && <div className="creator-detail-section"><EntitlementInspector userId={userId} canManage={canManage} />{canManageRoles && <RoleAccessManager user={user} onUpdated={detail.reload} />}</div>}
    <ConfirmDialog open={Boolean(confirm)} title="Confirm administrative action" message={`Lock-in will ${humanize(confirm?.action)} this account and record the stated reason in the immutable audit log.`} confirmLabel={pending ? "Working…" : "Confirm"} onCancel={() => setConfirm(null)} onConfirm={() => run(confirm.action, confirm.extra)} />
  </aside></>;
}

function RoleAccessManager({ user, onUpdated }) { const data = useAsyncData(() => Promise.all([adminControlApi.roleCatalog(), adminControlApi.userCapabilities(user.id)]).then(([catalog, capabilities]) => ({ catalog, capabilities })), [user.id]); const [selectedRoles, setSelectedRoles] = useState(user.operational_roles || []); const [selectedCapabilities, setSelectedCapabilities] = useState([]); const [selectedProductRoles, setSelectedProductRoles] = useState(user.product_roles || []); const [reason, setReason] = useState(""); const [pending, setPending] = useState(""); const [error, setError] = useState(null); const [confirm, setConfirm] = useState(null); useEffect(() => { if (data.data) { setSelectedCapabilities(data.data.capabilities.direct_capabilities.map((item) => item.code)); setSelectedRoles(user.operational_roles || []); setSelectedProductRoles(user.product_roles || []); } }, [data.data, user.operational_roles, user.product_roles]); function toggle(value, values, setValues) { setValues(values.includes(value) ? values.filter((item) => item !== value) : [...values, value]); } async function save(kind) { setPending(kind); setError(null); try { if (kind === "operational") await adminControlApi.updateOperationalRoles(user.id, selectedRoles, reason); if (kind === "capabilities") await adminControlApi.updateUserCapabilities(user.id, selectedCapabilities, reason); if (kind === "product") await adminControlApi.userAction(user.id, { action: "replace_product_roles", roles: selectedProductRoles.filter((role) => role !== "student"), reason }); setConfirm(null); onUpdated(); } catch (requestError) { setError(requestError); } finally { setPending(""); } } if (data.loading) return <LoadingPanel />; if (data.error) return <ErrorPanel message={data.error} onRetry={data.reload} />; return <section className="operations-inline-panel operations-role-manager"><h3>Roles and direct capabilities</h3><p>Role bundles and exceptional direct grants are both enforced. Unknown permissions are denied by default.</p><label className="field"><span>Reason for access change</span><input minLength={8} value={reason} onChange={(event) => setReason(event.target.value)} placeholder="Why is this access required?" /></label><Notice error={error} /><div className="operations-check-grid"><fieldset><legend>Operational roles</legend>{data.data.catalog.operational_roles.map((role) => <label className="check-row" key={role.code}><input type="checkbox" checked={selectedRoles.includes(role.code)} onChange={() => toggle(role.code, selectedRoles, setSelectedRoles)} /> {role.name}</label>)}<button className="btn btn-soft compact" type="button" disabled={reason.trim().length < 8 || Boolean(pending)} onClick={() => setConfirm("operational")}>Save operational roles</button></fieldset><fieldset><legend>Product roles</legend>{data.data.catalog.product_roles.filter((role) => role !== "student").map((role) => <label className="check-row" key={role}><input type="checkbox" checked={selectedProductRoles.includes(role)} onChange={() => toggle(role, selectedProductRoles, setSelectedProductRoles)} /> {humanize(role)}</label>)}<button className="btn btn-soft compact" type="button" disabled={reason.trim().length < 8 || Boolean(pending)} onClick={() => setConfirm("product")}>Save product roles</button></fieldset></div><details><summary>Exceptional direct capabilities ({selectedCapabilities.length})</summary><div className="operations-check-grid">{data.data.capabilities.catalog.map((capability) => <label className="check-row" key={capability.code}><input type="checkbox" checked={selectedCapabilities.includes(capability.code)} onChange={() => toggle(capability.code, selectedCapabilities, setSelectedCapabilities)} /> {capability.name}</label>)}</div><button className="btn btn-soft compact" type="button" disabled={reason.trim().length < 8 || Boolean(pending)} onClick={() => setConfirm("capabilities")}>Save direct capabilities</button></details><ConfirmDialog open={Boolean(confirm)} title="Confirm access change" message="Lock-in will validate the role or capability assignment, protect the final platform administrator, and write an immutable audit record." confirmLabel={pending ? "Saving…" : "Confirm"} onCancel={() => setConfirm(null)} onConfirm={() => save(confirm)} /></section>; }

function EntitlementInspector({ userId, canManage }) { const data = useAsyncData(() => adminControlApi.userEntitlements(userId), [userId]); const [entitlementCode, setEntitlementCode] = useState("focus.workspace"); const [endsAt, setEndsAt] = useState(""); const [reason, setReason] = useState(""); const [error, setError] = useState(null); const [pending, setPending] = useState(false); const [confirm, setConfirm] = useState(false); async function grant() { setPending(true); setError(null); try { await adminControlApi.grantEntitlement(userId, { entitlement_code: entitlementCode, ends_at: endsAt ? new Date(endsAt).toISOString() : null, reason }); setReason(""); setConfirm(false); data.reload(); } catch (requestError) { setError(requestError); } finally { setPending(false); } } if (data.loading) return <LoadingPanel />; if (data.error) return <ErrorPanel message={data.error} onRetry={data.reload} />; return <section className="operations-inline-panel"><div className="panel-title"><h3>Focus and entitlement inspector</h3><span>Server authority</span></div>{data.data.effective_permissions.map((entry) => <p key={entry.code}><b>{entry.code}</b>: {entry.allowed ? "Allowed" : "Denied"} · {entry.reason}{entry.expires_at ? ` · ends ${shortDate(entry.expires_at)}` : ""}</p>)}<details><summary>Active and historical grants ({data.data.grants.length})</summary>{data.data.grants.map((grant) => <p key={grant.id}>{grant.entitlement?.code || grant.entitlement_code} · {humanize(grant.status)} · {humanize(grant.source_type)}{grant.ends_at ? ` · ends ${shortDate(grant.ends_at)}` : ""}</p>)}</details>{canManage && <form className="operations-form" onSubmit={(event) => { event.preventDefault(); setConfirm(true); }}><label className="field"><span>Entitlement code</span><input value={entitlementCode} onChange={(event) => setEntitlementCode(event.target.value)} required /></label><label className="field"><span>Expiry (optional)</span><input type="datetime-local" value={endsAt} onChange={(event) => setEndsAt(event.target.value)} /></label><label className="field"><span>Administrative reason</span><input minLength={8} value={reason} onChange={(event) => setReason(event.target.value)} required /></label><Notice error={error} /><FormButton pending={pending}>Grant entitlement</FormButton></form>}<ConfirmDialog open={confirm} title="Confirm entitlement grant" message="Lock-in will validate the entitlement definition, calculate effective access, and record an immutable audit event." confirmLabel={pending ? "Working…" : "Grant access"} onCancel={() => setConfirm(false)} onConfirm={grant} /></section>; }

function SearchBar({ label, value, onChange, placeholder }) { return <label className="field operations-search"><span>{label}</span><input type="search" value={value} onChange={(event) => onChange(event.target.value)} placeholder={placeholder} /></label>; }


function Purchases({ operationsSession }) {
  const [query, setQuery] = useState(""); const [status, setStatus] = useState(""); const [page, setPage] = useState(1); const [selected, setSelected] = useState(null);
  const data = useAsyncData(() => adminControlApi.purchases({ page, query, status }), [page, query, status]);
  return <section className="operations-workspace"><div className="operations-filter-row"><SearchBar label="Search purchases" value={query} onChange={(value) => { setQuery(value); setPage(1); }} placeholder="Email, username, transaction, or plan" /><label className="field"><span>Status</span><select value={status} onChange={(event) => { setStatus(event.target.value); setPage(1); }}><option value="">All</option>{["pending_review", "approved", "rejected", "succeeded", "pending", "failed", "cancelled", "refunded", "partially_refunded"].map((item) => <option value={item} key={item}>{humanize(item)}</option>)}</select></label></div>{data.loading ? <LoadingPanel /> : data.error ? <ErrorPanel message={data.error} onRetry={data.reload} /> : <><section className="panel list-panel"><div className="panel-title"><h2>Payments</h2><span>{data.data.count}</span></div>{data.data.results.length ? data.data.results.map((purchase) => <button className="operations-row" type="button" key={purchase.id} onClick={() => setSelected(purchase.id)}><span className="stat-icon"><Icon name={purchase.method === "libyana" ? "coins" : "file"} /></span><span><b>{money(purchase.amount_minor, purchase.currency, purchase.currency_exponent)}</b><small>{purchase.user.username ? `@${purchase.user.username}` : purchase.user.email || "No account"} · {humanize(purchase.manual_submission?.status || purchase.status)} · {purchase.plan_title || purchase.transaction_id}</small></span>{purchase.manual_submission?.status === "pending" && <span className="creator-badge is-warning">Review</span>}<Icon name="chevron-right" /></button>) : <EmptyState title="No payments found" text="No payment matched these filters." />}</section><Pager page={page} count={data.data.count} onPage={setPage} /></>}{selected && <PurchaseDetail paymentId={selected} canManage={hasOperationalCapability(operationsSession, "payments.manage")} onClose={() => setSelected(null)} />}</section>;
}

function PurchaseDetail({ paymentId, canManage, onClose }) {
  const data = useAsyncData(() => adminControlApi.purchase(paymentId), [paymentId]);
  const [amount, setAmount] = useState(""); const [reason, setReason] = useState(""); const [error, setError] = useState(null); const [pending, setPending] = useState(false); const [confirm, setConfirm] = useState(false);
  async function refund() { setPending(true); setError(null); try { await adminControlApi.refund(paymentId, { amountMinor: amount, refundReason: reason }); data.reload(); setConfirm(false); } catch (requestError) { setError(requestError); } finally { setPending(false); } }
  if (data.loading) return <LoadingPanel />;
  if (data.error) return <ErrorPanel message={data.error} onRetry={data.reload} />;
  const payment = data.data;
  const manual = payment.manual_submission;
  return (
    <section className="panel operations-detail">
      <div className="panel-title"><div><p className="eyebrow">{payment.method === "libyana" ? "Libyana payment" : "Purchase"}</p><h2>{String(payment.id).slice(0, 8)}</h2></div><button className="btn btn-soft compact" type="button" onClick={onClose}>Close</button></div>
      <div className="operations-detail-grid">
        <div><p><b>{money(payment.amount_minor, payment.currency, payment.currency_exponent)}</b> · {humanize(manual?.status || payment.status)}</p><p>{payment.user.username ? `@${payment.user.username}` : payment.user.email} · {payment.plan_title || payment.plan_code || "No plan snapshot"}</p><p>{payment.user.email}</p></div>
        <div><p>Subscription: {manual ? `${shortDate(manual.subscription_period_started_at)} — ${shortDate(manual.subscription_period_ends_at)}` : "Provider managed"}</p><p>Invoice: {payment.invoice?.number || "Pending review"}</p><p>Submitted {shortDate(manual?.submitted_at || payment.created_at)}</p></div>
      </div>
      {manual && <ManualPaymentReviewPanel payment={payment} canManage={canManage} onUpdated={data.reload} />}
      <section className="operations-inline-panel"><h3>Payment history</h3>{payment.transitions?.map((entry) => <p key={entry.id}>{humanize(entry.from_status || "created")} → {humanize(entry.to_status)} · {shortDate(entry.effective_at)}</p>)}{payment.refunds?.map((item) => <p key={item.id}>Refund {money(item.amount_minor, payment.currency, payment.currency_exponent)} · {humanize(item.status)}</p>)}</section>
      {canManage && !manual && <form className="operations-form" onSubmit={(event) => { event.preventDefault(); setConfirm(true); }}><h3>Request a verified refund</h3><label className="field"><span>Amount in minor currency units</span><input inputMode="numeric" value={amount} onChange={(event) => setAmount(event.target.value)} required /></label><label className="field"><span>Administrative reason</span><input minLength={8} value={reason} onChange={(event) => setReason(event.target.value)} required /></label><Notice error={error} /><FormButton pending={pending}>Request refund</FormButton></form>}
      {canManage && !manual && <PaymentCorrectionPanel payment={payment} onUpdated={data.reload} />}
      <ConfirmDialog open={confirm} title="Request refund" message="Lock-in will validate the available refundable balance, call the configured provider, and audit this request." confirmLabel={pending ? "Requesting…" : "Request refund"} onCancel={() => setConfirm(false)} onConfirm={refund} />
    </section>
  );
}

function ManualPaymentReviewPanel({ payment, canManage, onUpdated }) {
  const submission = payment.manual_submission;
  const [reason, setReason] = useState(""); const [decision, setDecision] = useState(null); const [pending, setPending] = useState(false); const [error, setError] = useState(null);
  async function review() { if (!decision) return; setPending(true); setError(null); try { await adminControlApi.reviewManualPayment(payment.id, decision, reason); setDecision(null); onUpdated(); } catch (requestError) { setError(requestError); } finally { setPending(false); } }
  return <section className="operations-inline-panel manual-payment-review"><div className="panel-title"><h3>Recharge card</h3><span className={`creator-badge is-${submission.status === "pending" ? "warning" : submission.status === "approved" ? "healthy" : "danger"}`}>{humanize(submission.status)}</span></div><dl className="operations-detail-grid"><div><dt>Recharge code</dt><dd className="manual-recharge-code" dir="ltr">{submission.recharge_code || submission.recharge_code_masked}</dd></div><div><dt>Review</dt><dd>{submission.reviewed_by_name ? `${submission.reviewed_by_name} · ${shortDate(submission.reviewed_at)}` : "Awaiting an authorized reviewer"}</dd></div></dl>{submission.rejection_reason && <p className="form-alert error">{submission.rejection_reason}</p>}{canManage && submission.status === "pending" && <><label className="field"><span>Review reason</span><input minLength={3} maxLength={500} value={reason} onChange={(event) => setReason(event.target.value)} placeholder="Card valid or reason for rejection" /></label><Notice error={error} /><div className="operations-actions"><button className="btn btn-primary" type="button" disabled={pending || reason.trim().length < 3} onClick={() => setDecision("approve")}>Approve payment</button><button className="btn btn-danger" type="button" disabled={pending || reason.trim().length < 3} onClick={() => setDecision("reject")}>Reject payment</button></div></>}<ConfirmDialog open={Boolean(decision)} title={`${humanize(decision)} Libyana payment`} message={decision === "approve" ? "The provisional period will become verified without extending twice." : "Provisional access will be revoked. The account and all study data will remain saved."} confirmLabel={pending ? "Reviewing…" : humanize(decision)} onCancel={() => setDecision(null)} onConfirm={review} /></section>;
}

function PaymentCorrectionPanel({ payment, onUpdated }) { const [requestedStatus, setRequestedStatus] = useState("failed"); const [reference, setReference] = useState(""); const [reason, setReason] = useState(""); const [reviewReasons, setReviewReasons] = useState({}); const [pending, setPending] = useState(""); const [error, setError] = useState(null); const [confirm, setConfirm] = useState(false); const [reviewConfirm, setReviewConfirm] = useState(null); async function requestCorrection() { setPending("request"); setError(null); try { await adminControlApi.requestPaymentCorrection(payment.id, { requestedStatus, providerReference: reference, reason }); setConfirm(false); onUpdated(); } catch (requestError) { setError(requestError); } finally { setPending(""); } } async function review(correctionId, decision) { const reviewReason = reviewReasons[correctionId] || ""; setPending(correctionId); setError(null); try { await adminControlApi.reviewPaymentCorrection(correctionId, { decision, reason: reviewReason }); setReviewConfirm(null); onUpdated(); } catch (requestError) { setError(requestError); } finally { setPending(""); } } return <section className="operations-form operations-inline-panel"><h3>Controlled payment reconciliation</h3><p>Payment status is never edited directly. A request must include provider evidence and a different administrator must approve it.</p><label className="field"><span>Requested status</span><select value={requestedStatus} onChange={(event) => setRequestedStatus(event.target.value)}>{["succeeded", "failed", "cancelled"].map((value) => <option value={value} key={value}>{humanize(value)}</option>)}</select></label><label className="field"><span>Verified provider reference</span><input minLength={3} value={reference} onChange={(event) => setReference(event.target.value)} required /></label><label className="field"><span>Request reason</span><input minLength={8} value={reason} onChange={(event) => setReason(event.target.value)} required /></label><Notice error={error} /><button className="btn btn-outline" type="button" disabled={reference.trim().length < 3 || reason.trim().length < 8 || pending === "request"} onClick={() => setConfirm(true)}>Request independent review</button>{payment.status_corrections?.map((correction) => <article className="operations-campaign" key={correction.id}><div><h3>{humanize(correction.requested_status)} correction · {humanize(correction.status)}</h3><p>{correction.requested_by_name || "Operator"} · {shortDate(correction.created_at)}</p><small>{correction.reason}</small></div>{correction.status === "pending" && <div><input aria-label={`Review reason for correction ${correction.id}`} minLength={8} value={reviewReasons[correction.id] || ""} onChange={(event) => setReviewReasons({ ...reviewReasons, [correction.id]: event.target.value })} placeholder="Independent review reason" /><div className="operations-actions"><button className="btn btn-soft compact" type="button" disabled={pending === correction.id || (reviewReasons[correction.id] || "").trim().length < 8} onClick={() => setReviewConfirm({ id: correction.id, decision: "approve" })}>Approve</button><button className="btn btn-danger compact" type="button" disabled={pending === correction.id || (reviewReasons[correction.id] || "").trim().length < 8} onClick={() => setReviewConfirm({ id: correction.id, decision: "reject" })}>Reject</button></div></div>}</article>)}<ConfirmDialog open={confirm} title="Request independent correction review" message="This will not change payment status. It creates an audited request that a different administrator must review with provider evidence." confirmLabel={pending === "request" ? "Submitting…" : "Submit request"} onCancel={() => setConfirm(false)} onConfirm={requestCorrection} /><ConfirmDialog open={Boolean(reviewConfirm)} title="Confirm correction review" message="Lock-in will enforce separation of duties, validate the payment transition, and record this review in the audit log." confirmLabel={pending ? "Reviewing…" : humanize(reviewConfirm?.decision)} onCancel={() => setReviewConfirm(null)} onConfirm={() => review(reviewConfirm.id, reviewConfirm.decision)} /></section>; }

function Subscriptions({ operationsSession }) {
  const [query, setQuery] = useState(""); const [status, setStatus] = useState(""); const [page, setPage] = useState(1); const [selected, setSelected] = useState(null);
  const data = useAsyncData(() => adminControlApi.subscriptions({ page, query, status }), [page, query, status]);
  const summary = useAsyncData(() => adminControlApi.analytics(), []);
  return <section className="operations-workspace">{summary.data && <section className="creator-metrics creator-metrics-four"><MetricCard label="Active" value={formatNumber(summary.data.subscriptions.active)} hint="Includes grace access" icon="layers" tone="green" /><MetricCard label="Trials" value={formatNumber(summary.data.subscriptions.trial)} hint="Current trial periods" icon="clock" /><MetricCard label="Expiring soon" value={formatNumber(summary.data.subscriptions.upcoming_expirations)} hint="Next 14 days" icon="alert-triangle" tone="gold" /><MetricCard label="Expired" value={formatNumber(summary.data.subscriptions.expired)} hint="Historical records" icon="activity" /></section>}<div className="operations-filter-row"><SearchBar label="Search subscriptions" value={query} onChange={(value) => { setQuery(value); setPage(1); }} placeholder="Email or plan" /><label className="field"><span>Status</span><select value={status} onChange={(event) => { setStatus(event.target.value); setPage(1); }}><option value="">All</option>{["active", "trialing", "grace", "expired", "cancelled", "suspended"].map((item) => <option value={item} key={item}>{humanize(item)}</option>)}</select></label></div>{data.loading ? <LoadingPanel variant="list" /> : data.error ? <ErrorPanel message={data.error} onRetry={data.reload} /> : <><section className="creator-panel list-panel"><div className="creator-panel-heading"><div><p>Lifecycle</p><h2>Subscriptions</h2></div><span>{formatNumber(data.data.count)} records</span></div>{data.data.results.length ? data.data.results.map((subscription) => <button className="operations-row" type="button" key={subscription.id} onClick={() => setSelected(subscription.id)}><span className="stat-icon"><Icon name="layers" /></span><span><b>{subscription.plan_title || subscription.plan_code}</b><small>{subscription.user.email || "No account"} · {humanize(subscription.status)} · {subscription.remaining_days ?? "—"} days remaining</small></span><Icon name="chevron-right" /></button>) : <EmptyState title="No subscriptions found" text="No subscription matched these filters." />}</section><Pager page={page} count={data.data.count} onPage={setPage} /></>}{selected && <SubscriptionDetail subscriptionId={selected} canManage={hasOperationalCapability(operationsSession, "subscriptions.manage")} onClose={() => setSelected(null)} />}</section>;
}

function SubscriptionDetail({ subscriptionId, canManage, onClose }) {
  const data = useAsyncData(() => adminControlApi.subscription(subscriptionId), [subscriptionId]); const [reason, setReason] = useState(""); const [action, setAction] = useState("suspend"); const [expiration, setExpiration] = useState(""); const [error, setError] = useState(null); const [pending, setPending] = useState(false); const [confirm, setConfirm] = useState(false);
  async function mutate() { setPending(true); setError(null); try { const body = { action, reason }; if (["extend", "change_expiration"].includes(action)) body.period_ends_at = new Date(expiration).toISOString(); await adminControlApi.subscriptionAction(subscriptionId, body); data.reload(); setConfirm(false); } catch (requestError) { setError(requestError); } finally { setPending(false); } }
  if (data.loading) return <LoadingPanel />; if (data.error) return <ErrorPanel message={data.error} onRetry={data.reload} />; const item = data.data;
  return <section className="panel operations-detail"><div className="panel-title"><h2>{item.plan_title || item.plan_code}</h2><button className="btn btn-soft compact" type="button" onClick={onClose}>Close</button></div><p className="muted">{item.user.email} · {humanize(item.status)} · ends {shortDate(item.current_period_ends_at || item.trial_ends_at)}</p><section className="operations-inline-panel"><h3>Immutable history</h3>{item.admin_events?.length ? item.admin_events.map((event) => <p key={event.id}>{humanize(event.action)} by {event.actor_name || "operator"} · {shortDate(event.created_at)}</p>) : <p>No manual administrative subscription events.</p>}</section>{canManage && <form className="operations-form" onSubmit={(event) => { event.preventDefault(); setConfirm(true); }}><label className="field"><span>Subscription action</span><select value={action} onChange={(event) => setAction(event.target.value)}>{["activate", "reactivate", "suspend", "cancel_now", "cancel_period_end", "extend", "change_expiration"].map((value) => <option value={value} key={value}>{humanize(value)}</option>)}</select></label>{["extend", "change_expiration"].includes(action) && <label className="field"><span>Expiration date</span><input type="datetime-local" value={expiration} onChange={(event) => setExpiration(event.target.value)} required /></label>}<label className="field"><span>Administrative reason</span><input minLength={8} value={reason} onChange={(event) => setReason(event.target.value)} required /></label><Notice error={error} /><FormButton pending={pending}>Apply change</FormButton></form>}<ConfirmDialog open={confirm} title="Confirm subscription change" message="Lock-in will validate this lifecycle transition, synchronize entitlements, enforce idempotency, and record an immutable event." confirmLabel={pending ? "Applying…" : "Apply change"} onCancel={() => setConfirm(false)} onConfirm={mutate} /></section>;
}

function Notifications({ operationsSession }) {
  const [page, setPage] = useState(1); const [compose, setCompose] = useState(false); const data = useAsyncData(() => adminControlApi.campaigns({ page }), [page]); const canManage = hasOperationalCapability(operationsSession, "notifications.manage");
  return <section className="operations-workspace">{canManage && <button className="btn btn-primary" type="button" onClick={() => setCompose((open) => !open)}><Icon name="megaphone" size={16} /> {compose ? "Close composer" : "Create campaign"}</button>}{compose && <CampaignForm onSaved={() => { setCompose(false); data.reload(); }} />}{data.loading ? <LoadingPanel /> : data.error ? <ErrorPanel message={data.error} onRetry={data.reload} /> : <><section className="panel list-panel"><div className="panel-title"><h2>Notification campaigns</h2><span>{data.data.count}</span></div>{data.data.results.length ? data.data.results.map((campaign) => <CampaignRow key={campaign.id} campaign={campaign} canManage={canManage} onChanged={data.reload} />) : <EmptyState title="No campaigns" text="No administrative notification campaign has been created." />}</section><Pager page={page} count={data.data.count} onPage={setPage} /></>}</section>;
}

function ReportsCenter({ operationsSession }) { const [status, setStatus] = useState(""); const [selected, setSelected] = useState(null); const data = useAsyncData(() => adminControlApi.moderationReports({ status }), [status]); const canManage = hasOperationalCapability(operationsSession, "moderation.manage"); if (data.loading) return <LoadingPanel />; if (data.error) return <ErrorPanel message={data.error} onRetry={data.reload} />; return <section className="operations-workspace"><label className="field"><span>Report status</span><select value={status} onChange={(event) => setStatus(event.target.value)}><option value="">All statuses</option>{["open", "triaged", "in_progress", "resolved", "rejected", "duplicate"].map((value) => <option value={value} key={value}>{humanize(value)}</option>)}</select></label><section className="panel list-panel"><div className="panel-title"><h2>Reports and moderation</h2><span>Cursor-paginated</span></div>{data.data.results?.length ? data.data.results.map((report) => <button className="operations-row" type="button" key={report.id} onClick={() => setSelected(report)}><span className="stat-icon"><Icon name="messages" /></span><span><b>{report.target_label || humanize(report.target_type)}</b><small>{humanize(report.reason)} · {humanize(report.status)} · {humanize(report.priority)}</small></span><Icon name="chevron-right" /></button>) : <EmptyState title="No reports found" text="No report matches this server-side moderation filter." />}</section>{selected && <ModerationReportDetail report={selected} canManage={canManage} onClose={() => setSelected(null)} onUpdated={() => { setSelected(null); data.reload(); }} />}</section>; }
function ModerationReportDetail({ report, canManage, onClose, onUpdated }) { const [nextStatus, setNextStatus] = useState("triaged"); const [notes, setNotes] = useState(""); const [error, setError] = useState(null); const [pending, setPending] = useState(false); const [confirm, setConfirm] = useState(false); async function transition() { setPending(true); setError(null); try { await adminControlApi.transitionModerationReport(report.id, { expected_revision: report.revision, status: nextStatus, resolution_notes: notes }); setConfirm(false); onUpdated(); } catch (requestError) { setError(requestError); } finally { setPending(false); } } return <section className="panel operations-detail"><div className="panel-title"><h2>{report.target_label || humanize(report.target_type)}</h2><button className="btn btn-soft compact" type="button" onClick={onClose}>Close</button></div><p>{report.description}</p><p className="muted">Reported by {report.reporter_name} · {humanize(report.reason)} · {humanize(report.priority)}</p>{canManage && <form className="operations-form" onSubmit={(event) => { event.preventDefault(); setConfirm(true); }}><label className="field"><span>Moderation status</span><select value={nextStatus} onChange={(event) => setNextStatus(event.target.value)}>{["triaged", "in_progress", "resolved", "rejected"].map((value) => <option value={value} key={value}>{humanize(value)}</option>)}</select></label><label className="field"><span>Resolution note</span><textarea value={notes} onChange={(event) => setNotes(event.target.value)} maxLength={4000} /></label><Notice error={error} /><FormButton pending={pending}>Apply moderation decision</FormButton></form>}<ConfirmDialog open={confirm} title="Confirm moderation decision" message="Lock-in will validate the report revision and authorization, record moderation history, and create a platform audit event." confirmLabel={pending ? "Applying…" : "Apply decision"} onCancel={() => setConfirm(false)} onConfirm={transition} /></section>; }

function CampaignForm({ onSaved }) {
  const [form, setForm] = useState({ audience: "all_users", title: "", body: "", send_in_app: true, send_email: false, scheduled_for: "", user_id: "", user_ids: "", plan_code: "", reason: "" });
  const [pending, setPending] = useState(false); const [error, setError] = useState(null);
  function update(key, value) { setForm((current) => ({ ...current, [key]: value })); }
  function audienceFilter() {
    if (form.audience === "user") return { user_id: form.user_id.trim() };
    if (form.audience === "selected_users") return { user_ids: form.user_ids.split(/[\s,]+/).filter(Boolean) };
    if (form.audience === "plan_users") return { plan_code: form.plan_code.trim() };
    return {};
  }
  async function submit(event) { event.preventDefault(); setPending(true); setError(null); try { await adminControlApi.createCampaign({ ...form, scheduled_for: form.scheduled_for ? new Date(form.scheduled_for).toISOString() : null, audience_filter: audienceFilter() }); onSaved(); } catch (requestError) { setError(requestError); } finally { setPending(false); } }
  return <form className="panel operations-form" onSubmit={submit}><div className="panel-title"><h2>New campaign</h2><span>Real recipients only</span></div><label className="field"><span>Audience</span><select value={form.audience} onChange={(event) => update("audience", event.target.value)}>{[["all_users", "All active users"], ["active_subscribers", "Active subscribers"], ["expired_subscribers", "Expired subscribers"], ["trial_users", "Trial users"], ["creators", "Creators"], ["user", "One user"], ["selected_users", "Selected users"], ["plan_users", "Users on a plan"]].map(([value, label]) => <option value={value} key={value}>{label}</option>)}</select></label>{form.audience === "user" && <label className="field"><span>User UUID</span><input value={form.user_id} onChange={(event) => update("user_id", event.target.value)} required /></label>}{form.audience === "selected_users" && <label className="field"><span>User UUIDs</span><textarea value={form.user_ids} onChange={(event) => update("user_ids", event.target.value)} placeholder="One UUID per line or comma-separated" required /></label>}{form.audience === "plan_users" && <label className="field"><span>Plan code</span><input value={form.plan_code} onChange={(event) => update("plan_code", event.target.value)} required /></label>}<label className="field"><span>Title</span><input maxLength={160} value={form.title} onChange={(event) => update("title", event.target.value)} required /></label><label className="field"><span>Message</span><textarea maxLength={320} value={form.body} onChange={(event) => update("body", event.target.value)} required /></label><label className="field"><span>Scheduled delivery (optional)</span><input type="datetime-local" value={form.scheduled_for} onChange={(event) => update("scheduled_for", event.target.value)} /></label><label className="check-row"><input type="checkbox" checked={form.send_in_app} onChange={(event) => update("send_in_app", event.target.checked)} /> In-app notification</label><label className="check-row"><input type="checkbox" checked={form.send_email} onChange={(event) => update("send_email", event.target.checked)} /> Email where configured</label><label className="field"><span>Administrative reason</span><input minLength={8} value={form.reason} onChange={(event) => update("reason", event.target.value)} required /></label><Notice error={error} /><FormButton pending={pending}>Save campaign</FormButton></form>;
}
function CampaignRow({ campaign, canManage, onChanged }) { const [reason, setReason] = useState(""); const [error, setError] = useState(null); const [pending, setPending] = useState(false); const [confirm, setConfirm] = useState(false); async function dispatch() { setPending(true); setError(null); try { await adminControlApi.dispatchCampaign(campaign.id, reason); onChanged(); setConfirm(false); } catch (requestError) { setError(requestError); } finally { setPending(false); } } return <article className="operations-campaign"><div><h3>{campaign.title}</h3><p>{humanize(campaign.audience)} · {humanize(campaign.status)} · {campaign.delivered_count} delivered · {campaign.failed_count} failed</p><small>{campaign.body}</small></div>{canManage && ["draft", "scheduled"].includes(campaign.status) && <div><input aria-label={`Reason to dispatch ${campaign.title}`} minLength={8} value={reason} onChange={(event) => setReason(event.target.value)} placeholder="Dispatch reason" /><button className="btn btn-soft compact" type="button" disabled={reason.trim().length < 8 || pending} onClick={() => setConfirm(true)}>Dispatch</button><Notice error={error} /></div>}<ConfirmDialog open={confirm} title="Dispatch campaign" message="Lock-in will select the actual audience at dispatch time, track each delivery, and record the operation." confirmLabel={pending ? "Dispatching…" : "Dispatch"} onCancel={() => setConfirm(false)} onConfirm={dispatch} /></article>; }

function AuditLog() { const [page, setPage] = useState(1); const [domain, setDomain] = useState(""); const data = useAsyncData(() => adminControlApi.audit({ page, domain }), [page, domain]); if (data.loading) return <LoadingPanel variant="list" />; if (data.error) return <ErrorPanel message={data.error} onRetry={data.reload} />; return <section className="operations-workspace"><div className="creator-page-tools"><div><p>Immutable history</p><h2>Administrative activity</h2><span>Reasons and actors are recorded.</span></div><label className="field"><span>Domain</span><select value={domain} onChange={(event) => { setDomain(event.target.value); setPage(1); }}><option value="">All domains</option>{["accounts", "subscriptions", "payments", "content", "notifications", "configuration"].map((value) => <option value={value} key={value}>{humanize(value)}</option>)}</select></label></div><section className="creator-panel list-panel"><div className="creator-panel-heading"><div><p>Audit log</p><h2>Recorded actions</h2></div><span>{formatNumber(data.data.count)} records</span></div>{data.data.results.length ? data.data.results.map((record) => <article className="list-row" key={record.id}><span className="stat-icon"><Icon name="activity" /></span><div><h2>{humanize(record.action)}</h2><p>{record.actor_name || "System"} · {record.reason} · {shortDate(record.occurred_at)}</p></div><span className="pill">{record.domain}</span></article>) : <EmptyState title="No audit records" text="No audit event is visible for this filter and permission." />}</section><Pager page={page} count={data.data.count} onPage={setPage} /></section>; }

function ConfigurationEditor({ entry, onSaved }) {
  const [value, setValue] = useState(entry.value);
  const [reason, setReason] = useState("");
  const [error, setError] = useState(null);
  const [pending, setPending] = useState(false);
  const [confirm, setConfirm] = useState(false);

  useEffect(() => { setValue(entry.value); }, [entry.value, entry.version]);

  async function save() {
    setPending(true); setError(null);
    try {
      await adminControlApi.updateConfiguration(entry.key, {
        value,
        expectedVersion: entry.version,
        changeReason: reason
      });
      setReason(""); setConfirm(false); onSaved();
    } catch (requestError) { setError(requestError); }
    finally { setPending(false); }
  }

  const control = entry.value_type === "boolean"
    ? <label className="check-row"><input type="checkbox" checked={Boolean(value)} onChange={(event) => setValue(event.target.checked)} /> Enabled</label>
    : <input type={entry.value_type === "integer" ? "number" : "text"} value={value ?? ""} min={entry.minimum ?? undefined} max={entry.maximum ?? undefined} onChange={(event) => setValue(entry.value_type === "integer" ? Number(event.target.value) : event.target.value)} />;

  return <details className="operations-setting" key={entry.key}><summary><span><strong>{entry.name || entry.key}</strong><small>Version {entry.version}{entry.updated_at ? ` · Updated ${shortDate(entry.updated_at)}` : ""}</small></span><Icon name="chevron-right" size={18} /></summary><div className="operations-setting-detail"><p>{entry.description || entry.key}</p><form className="operations-setting-form" onSubmit={(event) => { event.preventDefault(); setConfirm(true); }}><label className="field"><span>Value</span>{control}</label><label className="field"><span>Administrative reason</span><input minLength={8} maxLength={500} value={reason} onChange={(event) => setReason(event.target.value)} required /></label><Notice error={error} /><FormButton pending={pending} className="btn btn-soft compact">Save</FormButton></form></div><ConfirmDialog open={confirm} title="Confirm platform setting" message="Lock-in will validate this typed setting, reject a stale version, and create an immutable audit record." confirmLabel={pending ? "Saving…" : "Save setting"} onCancel={() => setConfirm(false)} onConfirm={save} /></details>;
}

function SettingsArea({ operationsSession }) {
  const data = useAsyncData(() => adminControlApi.configurations(), []);
  if (data.loading) return <LoadingPanel />;
  if (data.error) return <ErrorPanel message={data.error} onRetry={data.reload} />;
  const entries = data.data.results || data.data;
  const canManage = hasOperationalCapability(operationsSession, "configuration.manage");
  return <section className="panel list-panel"><div className="panel-title"><h2>Platform settings</h2><span>{canManage ? "Controlled changes" : "Read only"}</span></div>{Array.isArray(entries) && entries.length ? entries.map((entry) => canManage ? <ConfigurationEditor key={entry.key} entry={entry} onSaved={data.reload} /> : <article className="list-row" key={entry.key}><span className="stat-icon"><Icon name="settings" /></span><div><h2>{entry.name || entry.key}</h2><p>{entry.description || entry.key}</p></div><span className="pill">{String(entry.value)}</span></article>) : <EmptyState title="No settings available" text="No non-secret configuration entries are available for this role." />}</section>;
}

function SystemStatus() { const data = useAsyncData(() => adminControlApi.systemHealth(), []); if (data.loading) return <LoadingPanel />; if (data.error) return <ErrorPanel message={data.error} onRetry={data.reload} />; const health = data.data; return <section className="operations-workspace"><div className="creator-page-tools"><div><p>Platform health</p><h2>{health.status === "ok" ? "All core systems operational" : "Some systems need attention"}</h2><span>Checked {shortDate(health.checked_at)}. Infrastructure details are intentionally redacted.</span></div><span className={`creator-health-summary is-${health.status}`}><Icon name={health.status === "ok" ? "check" : "alert-triangle"} size={18} />{humanize(health.status)}</span></div><section className="creator-health-grid">{health.components.map((component) => <article className="creator-panel" key={component.code}><span className={`creator-component-icon is-${component.status}`}><Icon name={component.status === "ok" || component.status === "configured" ? "check" : component.status === "unavailable" ? "alert-triangle" : "activity"} size={19} /></span><div><h3>{humanize(component.code)}</h3><p>{component.freshness ? `Fresh as of ${shortDate(component.freshness)}` : component.status === "not_configured" ? "Optional provider not configured" : "Safe operational check"}</p></div><span className={`creator-badge is-${component.status}`}>{humanize(component.status)}</span></article>)}</section></section>; }

function Exports() { const data = useAsyncData(() => adminControlApi.reports(), []); const [status, setStatus] = useState(""); const [error, setError] = useState(null); async function download(report, format) { setStatus(`${report.code}:${format}`); setError(null); try { const preview = await adminControlApi.previewReport(report.code, {}, format); const blob = await adminControlApi.executeReport(preview.id, preview.confirmation_token); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = `${report.code}.${format}`; link.click(); URL.revokeObjectURL(url); } catch (requestError) { setError(requestError); } finally { setStatus(""); } } if (data.loading) return <LoadingPanel />; if (data.error) return <ErrorPanel message={data.error} onRetry={data.reload} />; return <section className="panel list-panel"><div className="panel-title"><h2>Secure exports</h2><span>CSV or Excel</span></div><Notice error={error} />{data.data.results?.length ? data.data.results.map((report) => <article className="list-row" key={report.code}><span className="stat-icon"><Icon name="file" /></span><div><h2>{report.name}</h2><p>{report.description}</p></div><div className="operations-actions"><button className="btn btn-soft compact" type="button" disabled={Boolean(status)} onClick={() => download(report, "csv")}>{status === `${report.code}:csv` ? "Preparing…" : "CSV"}</button><button className="btn btn-outline compact" type="button" disabled={Boolean(status)} onClick={() => download(report, "xlsx")}>{status === `${report.code}:xlsx` ? "Preparing…" : "Excel"}</button></div></article>) : <EmptyState title="No exports available" text="No export report is granted to this operational role." />}</section>; }

function Plans({ operationsSession }) {
  const data = useAsyncData(() => adminControlApi.plans(), []);
  const canManage = hasOperationalCapability(operationsSession, "subscriptions.manage");
  if (data.loading) return <LoadingPanel />;
  if (data.error) return <ErrorPanel message={data.error} onRetry={data.reload} />;
  return <section className="operations-workspace">{canManage && <PlanPriceEditor plans={data.data.results || []} onSaved={data.reload} />}<section className="panel list-panel"><div className="panel-title"><h2>Subscription plans</h2><span>{canManage ? "Configurable" : "Read only"}</span></div>{data.data.results?.length ? data.data.results.map((plan) => { const current = plan.versions?.find((version) => version.id === plan.current_version_id); const price = current?.prices?.[0]; return <article className="list-row" key={plan.id}><span className="stat-icon"><Icon name="layers" /></span><div><h2>{current?.title || plan.code}</h2><p>{humanize(plan.status)} · {price ? money(price.amount_minor, price.currency, price.currency_exponent) : "No published price"} · {price ? `${price.interval_count} ${price.interval}` : `${current?.trial_days || 0} trial days`}</p></div><span className="pill">{plan.product?.title}</span></article>; }) : <EmptyState title="No plans" text="No subscription plans are available." />}</section></section>;
}

function PlanPriceEditor({ plans, onSaved }) {
  const configurablePlans = plans.filter((plan) => plan.versions?.some((version) => version.prices?.length));
  const [planId, setPlanId] = useState(configurablePlans[0]?.id || ""); const [price, setPrice] = useState("10"); const [duration, setDuration] = useState("30"); const [enabled, setEnabled] = useState(true); const [reason, setReason] = useState(""); const [pending, setPending] = useState(false); const [error, setError] = useState(null); const [confirm, setConfirm] = useState(false);
  const plan = plans.find((item) => item.id === planId); const current = plan?.versions?.find((version) => version.id === plan.current_version_id) || plan?.versions?.at(-1); const nextVersion = Math.max(0, ...(plan?.versions || []).map((version) => Number(version.version) || 0)) + 1;
  async function save() { if (!plan || !current) return; setPending(true); setError(null); try { const wholePrice = Number(price); const days = Number(duration); const amountMinor = Math.round(wholePrice * 1000); await adminControlApi.createPlanVersion({ product_id: plan.product.id, plan_code: plan.code, title: current.title, description: current.description || "", audience: current.audience || "individual", trial_days: 0, grace_days: Number(current.grace_days || 7), terms: current.terms || {}, prices: [{ code: `${plan.code}_v${nextVersion}_${amountMinor}`, amount_minor: amountMinor, currency: "LYD", currency_exponent: 3, interval: "day", interval_count: days, region_code: "LY" }], entitlements: (current.entitlements || []).map((item) => ({ entitlement_code: item.code, quantity_limit: item.quantity_limit, configuration: item.configuration || {} })), publish: enabled, reason }); if (!enabled) await adminControlApi.planAction(plan.id, { action: "retire", reason }); setConfirm(false); setReason(""); onSaved(); } catch (requestError) { setError(requestError); } finally { setPending(false); } }
  if (!configurablePlans.length) return null;
  return <form className="panel operations-form plan-price-editor" onSubmit={(event) => { event.preventDefault(); setConfirm(true); }}><div className="panel-title"><div><p className="eyebrow">Plan configuration</p><h2>Libyana price and duration</h2></div><span>LYD</span></div><div className="operations-detail-grid"><label className="field"><span>Plan</span><select value={planId} onChange={(event) => setPlanId(event.target.value)}>{configurablePlans.map((item) => <option value={item.id} key={item.id}>{item.versions?.find((version) => version.id === item.current_version_id)?.title || item.code}</option>)}</select></label><label className="field"><span>Price (LYD)</span><input type="number" min="1" max="10000" step="0.001" value={price} onChange={(event) => setPrice(event.target.value)} required /></label><label className="field"><span>Duration (days)</span><input type="number" min="1" max="120" value={duration} onChange={(event) => setDuration(event.target.value)} required /></label><label className="check-row"><input type="checkbox" checked={enabled} onChange={(event) => setEnabled(event.target.checked)} /> Plan enabled</label></div><label className="field"><span>Administrative reason</span><input minLength={8} maxLength={500} value={reason} onChange={(event) => setReason(event.target.value)} placeholder="Why is this pricing changing?" required /></label><Notice error={error} /><FormButton pending={pending}>Save new plan version</FormButton><ConfirmDialog open={confirm} title="Publish subscription pricing" message="This creates an audited, immutable plan version. Existing subscriptions keep their recorded dates; new purchases use the new server price and duration." confirmLabel={pending ? "Saving…" : "Save pricing"} onCancel={() => setConfirm(false)} onConfirm={save} /></form>;
}

export default function OperationsAdmin({ operationsSession }) {
  const location = useLocation(); const navigate = useNavigate();
  const requested = location.pathname.split("/").filter(Boolean).at(-1);
  const allowed = useMemo(() => TABS.filter(([, , capability]) => hasOperationalCapability(operationsSession, capability)), [operationsSession]);
  const active = allowed.some(([key]) => key === requested) ? requested : allowed[0]?.[0] || "overview";
  useEffect(() => { if (allowed.length && requested !== active) navigate(`/operations/admin/${active}`, { replace: true }); }, [active, allowed.length, navigate, requested]);
  const initialQuery = new URLSearchParams(location.search).get("q") || "";
  const content = active === "overview" ? <Overview /> : active === "analytics" ? <Analytics /> : active === "users" ? <Users operationsSession={operationsSession} initialQuery={initialQuery} /> : active === "content" ? <AdminContentManagement operationsSession={operationsSession} initialArea="sheets" /> : active === "questions" ? <AdminContentManagement operationsSession={operationsSession} initialArea="questions" /> : active === "purchases" ? <Purchases operationsSession={operationsSession} /> : active === "subscriptions" ? <><Subscriptions operationsSession={operationsSession} /><Plans operationsSession={operationsSession} /></> : active === "notifications" ? <Notifications operationsSession={operationsSession} /> : active === "reports" ? <ReportsCenter operationsSession={operationsSession} /> : active === "audit" ? <AuditLog /> : active === "settings" ? <SettingsArea operationsSession={operationsSession} /> : active === "system" ? <SystemStatus /> : active === "exports" ? <Exports /> : <ErrorPanel message="This Creator Studio area is not available for the current server permission." />;
  return <Page title="Creator Studio" showHeading={false}><div className="creator-studio"><AdminTabs operationsSession={operationsSession} active={active} /><main className="creator-studio-main"><CreatorStudioHeader active={active} allowed={allowed} /><div className="creator-studio-content">{content}</div></main></div></Page>;
}
